{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 7,
      "text_ar": "ولكن ماذا عن أولئك الذين صلّيت لأجلهم؟ لأنه من هو من الأحياء الذي لم يُخطئ، ومن من بني البشر لم يتعدَ عهدك؟",
      "verse": 46
    },
    {
      "chapter": 7,
      "text_ar": "والآن أرى أن العالم الآتي سيجلب مسرة لقليلين، ولكن عذاباً لكثيرين.",
      "verse": 47
    },
    {
      "chapter": 7,
      "text_ar": "لأنه قد نما فينا قلب شرير، وهو الذي أضلنا عن هذه الوصايا وأدخلنا في الفساد وفي طرق الموت، وأرانا سبل الهلاك وأبعدنا جداً عن الحياة؛ وليس هذا لقليلين فقط، بل لكل من خُلقوا تقريبا.",
      "verse": 48
    },
    {
      "chapter": 7,
      "text_ar": "فأجابني قائلاً: استمع إليَّ فأعلمك، وأنذرك أيضاً.",
      "verse": 49
    },
    {
      "chapter": 7,
      "text_ar": "لهذا السبب لم يصنع العلي عالماً واحداً بل عالمين.",
      "verse": 50
    }
  ]
}
